<?php
namespace App\Services;
use App\Support\DigitalMarketingPermissions;use App\Support\MarketingCrudPermissions;use Illuminate\Contracts\Auth\Authenticatable;use Illuminate\Support\Facades\DB;
final class MarketingAssetAuthorization { public function __construct(private readonly MarketingAccessService $access){} public function assert(Authenticatable $user,int $clientId,string $permission):void{$this->access->assertClientAccess($user,$clientId);abort_unless((bool)data_get($user,'isAdmin',false)||DB::table('user_client')->where('user_id',$user->getAuthIdentifier())->where('client_id',$clientId)->exists(),403,'Anda tidak memiliki assignment langsung ke client aset ini.');$role=DigitalMarketingPermissions::role($user);$allowed=(bool)data_get($user,'isAdmin',false)||DigitalMarketingPermissions::isManager($role)||($permission!==MarketingCrudPermissions::ASSET_METADATA_ARCHIVE&&$role==='Digital Marketing');abort_unless($allowed,403,'Anda tidak memiliki permission metadata aset.');} public function object(Authenticatable $user,int $id,string $permission):object{$row=DB::table('marketing_asset_metadata')->where('id',$id)->first(['id','client_id','current_version','archived_at']);abort_unless($row,404,'Metadata aset tidak ditemukan.');$this->assert($user,(int)$row->client_id,$permission);return $row;} }
